    12→namespace Nethermind.Evm.TransactionProcessing;
    13→
    14→public sealed class SystemTransactionProcessor : TransactionProcessorBase
    15→{
    16→    private readonly bool _isAura;
    17→
    18→    /// <summary>
    19→    /// Hacky flag to execution options, to pass information how original validate should behave.
    20→    /// Needed to decide if we need to subtract transaction value.
    21→    /// </summary>
    22→    private const int OriginalValidate = 2 << 30;
    23→
    24→    public SystemTransactionProcessor(ISpecProvider? specProvider,
    25→        IWorldState? worldState,
    26→        IVirtualMachine? virtualMachine,
    27→        ICodeInfoRepository? codeInfoRepository,
    28→        ILogManager? logManager)
    29→        : base(specProvider, worldState, virtualMachine, codeInfoRepository, logManager)
    30→    {
    31→        _isAura = SpecProvider.SealEngine == SealEngineType.AuRa;
    32→    }
    33→
    34→    protected override TransactionResult Execute(Transaction tx, ITxTracer tracer, ExecutionOptions opts)
    35→    {
